import { Icon, NoData } from '@cetus/ui-kit'
import { Button, HStack, StackProps, Text } from '@chakra-ui/react'

interface FetchErrorProps extends StackProps {
  onClick: () => void
}

function FetchError({ onClick, ...rest }: FetchErrorProps) {
  return (
    <NoData type="nodata" text="Something went wrong" {...rest}>
      <Button mt="16px" p={{ base: '0 16px', lg: '0 32px' }} onClick={onClick} cursor="pointer">
        <HStack>
          <Icon xlinkHref="#icon-icon_refresh" svgFill="bg_secondary" svgHover="bg_secondary" svgH="bg_secondary" />
          <Text fontWeight="500" fontSize="14px" color="bg_secondary">
            Refresh
          </Text>
        </HStack>
      </Button>
    </NoData>
  )
}

export default FetchError
